src = open(sys.argv[1], encoding="utf-8").read().split("\n")
out, at, false = [], None, []
for l in src:
    m = re.match(r"^· (\S+) \[", l)
    if m: at = m.group(1); continue
    m = re.match(r"^\s+>\s+(\d+) \| (.*)$", l)
    if m and at:
        assert at.endswith(":" + m.group(1)), (at, l)
        f = at.rsplit(":", 1)[0]
        if at in FALSE: false.append(at); at = None; continue
        if at in REPORTED: out.append({"at": at, "says": m.group(2).strip(), "verdict": "reported", "why": REPORTED[at]})
        else:
            why = LINE.get(at) or FILE[f]
            assert why != "(see REPORTED)" and "REPORTED" not in why, at
            out.append({"at": at, "says": m.group(2).strip(), "verdict": "true", "why": why})
        at = None
assert sorted(false) == sorted(FALSE), (false, FALSE)
json.dump(out, open(sys.argv[2], "w", encoding="utf-8"), indent=1, ensure_ascii=False)
t = sum(x["verdict"] == "true" for x in out); r = sum(x["verdict"] == "reported" for x in out)
print(f"rulings: {len(out)} lines in {len({x['at'].rsplit(':',1)[0] for x in out})} files · true {t} · reported {r} · left unruled (false by the patch) {len(false)}: {', '.join(false)}")
